// Parse và validate JSON từ AI output
try {
  const eventData = JSON.parse($input.first().json.output);

  // Validate required fields
  const requiredFields = ['name', 'start', 'stop', 'privacy', 'show_as', 'active', 'user_id'];
  for (const field of requiredFields) {
    if (!eventData[field]) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  // Function để chuyển UTC+7 về UTC (trừ 7 giờ)
  function convertToUTC(timeString) {
    const date = new Date(timeString + '+07:00'); // Thêm timezone +07:00
    return date.toISOString().slice(0, 19).replace('T', ' '); // Format về YYYY-MM-DD HH:MM:SS
  }

  // Convert start và stop time về UTC
  if (eventData.start) {
    eventData.start = convertToUTC(eventData.start);
  }
  if (eventData.stop) {
    eventData.stop = convertToUTC(eventData.stop);
  }

  // Tính duration nếu chưa có hoặc validate
  if (eventData.start && eventData.stop) {
    const startTime = new Date(eventData.start);
    const stopTime = new Date(eventData.stop);
    const calculatedDuration = (stopTime - startTime) / (1000 * 60 * 60); // Convert to hours

    if (!eventData.duration || Math.abs(eventData.duration - calculatedDuration) > 0.1) {
      eventData.duration = calculatedDuration;
    }
  }

  // Validate duration > 0
  if (eventData.duration <= 0) {
    throw new Error('Duration must be greater than 0');
  }

  // Set defaults cho các field optional
  eventData.description = eventData.description || '';
  eventData.location = eventData.location || '';
  eventData.allday = eventData.allday || false;

  // Validate privacy values
  const validPrivacy = ['public', 'private', 'confidential'];
  if (!validPrivacy.includes(eventData.privacy)) {
    eventData.privacy = 'public';
  }

  // Validate show_as values
  const validShowAs = ['free', 'busy'];
  if (!validShowAs.includes(eventData.show_as)) {
    eventData.show_as = 'busy';
  }

  return {
    success: true,
    data: eventData,
    message: 'Event data processed successfully'
  };

} catch (error) {
  return {
    success: false,
    error: error.message,
    data: null
  };
}

// Format success response
const eventResult = $input.first().json;
const originalData = $('Check Processing Success').first().json.data;

// Convert UTC time back to UTC+7 for display
function convertToUTC7(utcTimeString) {
  const utcDate = new Date(utcTimeString + 'Z'); // Add Z to indicate UTC
  const utc7Date = new Date(utcDate.getTime() + (7 * 60 * 60 * 1000)); // Add 7 hours
  return utc7Date.toISOString().slice(0, 19).replace('T', ' ');
}

return {
  success: true,
  message: `Đã tạo thành công sự kiện: ${originalData.name}`,
  event_id: eventResult.id,
  event_data: {
    name: originalData.name,
    start: convertToUTC7(originalData.start), // Display in UTC+7
    stop: convertToUTC7(originalData.stop),   // Display in UTC+7
    duration: originalData.duration,
    location: originalData.location || '',
    description: originalData.description || '',
    privacy: originalData.privacy,
    show_as: originalData.show_as,
    allday: originalData.allday
  },
  odoo_url: `/web#id=${eventResult.id}&view_type=form&model=calendar.event`
};

// Format error response
const errorData = $input.first().json;

return {
  success: false,
  message: `Lỗi khi xử lý dữ liệu sự kiện: ${errorData.error}`,
  error: errorData.error,
  event_data: null
};
